{
  "messages": [
    {"role": "system", "content": "You extract a regulation citation. Reply with JSON having exactly two fields: `regulation` (a string, one of GDPR or EU AI Act) and `article` (an integer)."},
    {"role": "user", "content": "Which article of the GDPR requires a record of processing activities?"}
  ],
  "response_format": {
    "type": "json_schema",
    "json_schema": {
      "name": "citation",
      "schema": {
        "type": "object",
        "properties": {
          "regulation": {"type": "string"},
          "article": {"type": "integer"}
        },
        "required": ["regulation", "article"],
        "additionalProperties": false
      }
    }
  },
  "temperature": 0.7
}

