{
  "orgId": "{{org_id}}",
  "delegation": "",
  "signal": "We are a 40 person recruitment agency. We hold candidate CVs and employee payroll records, and we have never written down what we do with them.",
  "obligations": [
    {
      "slug": "gdpr-art-30-ropa",
      "title": "Records of Processing Activities",
      "summary": "Article 30 GDPR requires a written record of what you do with personal data, why, and for how long. The 250-employee exemption in Article 30(5) is narrow (it does not apply where processing is not occasional, involves special categories, or is likely to result in a risk to data subjects) so most SMEs cannot rely on it.",
      "appliesBecause": [
        "your organisation is recorded as a controller of personal data",
        "your compliance record does not show a record of processing activities"
      ]
    }
  ],
  "modelEndpoint": null
}
